# ══════════════════════════════════════════════════════════════
#  Auto-Aufgaben (Dashboard): mehrere unabhaengige geplante Aufgaben je
#  Server – anders als der Neustart-Zeitplan aus /auto restart (EIN
#  Zeitplan, 15/5/1-Minuten-Ankuendigungen) laufen diese hier lautlos ab
#  und melden sich nur per Wahl-Channel, wenn sie tatsaechlich ausgefuehrt
#  wurden. Bewusst getrennte Systeme, kein Ersatz fuereinander.
# ══════════════════════════════════════════════════════════════
# Registrierte Aufgaben-Typen – weitere kommen spaeter dazu (die Ausfuehrung
# je Typ steht in _scheduled_task_ausfuehren).
#
# ``channel_pflicht``: Aufgaben, die AUS der Nachricht bestehen statt eine
# Aktion zu quittieren. Ohne Channel liefen sie ins Leere, deshalb laesst sich
# "Channel ignorieren" dort nicht setzen.
# ``schaden``: (Schluessel in der cfggameplay.json, neuer Wert). Der Wert ist
# das VERBOT, nicht die Erlaubnis – "Schaden an" heisst disableXxxDamage=False.
SCHEDULED_TASK_TYPES: Dict[str, Dict[str, Any]] = {
    "restart_server": {"label": "Server neu starten"},
    "online_list": {"label": "Online-Liste posten", "channel_pflicht": True,
                    "online_liste_optionen": True},
    "base_damage_on":       {"label": "Base Damage anschalten",
                             "schaden": ("disableBaseDamage", False)},
    "base_damage_off":      {"label": "Base Damage ausschalten",
                             "schaden": ("disableBaseDamage", True)},
    "container_damage_on":  {"label": "Container Damage anschalten",
                             "schaden": ("disableContainerDamage", False)},
    "container_damage_off": {"label": "Container Damage ausschalten",
                             "schaden": ("disableContainerDamage", True)},
}

# Zwei unabhaengige Grenzen: zu VIELE Namen machen den Post nur unlesbar
# (_ONLINE_LISTE_MAX), zu LANGE Namen (Klammer-/Stern-Dekoration in
# Clan-Tags, die escape_markdown zusaetzlich verdoppelt) koennen dagegen
# Discords 4096-Zeichen-Grenze der Embed-Beschreibung sprengen – dann lehnt
# Discord den GANZEN Post ab. Deshalb wird zusaetzlich nach Zeichen gekappt.
_ONLINE_LISTE_MAX = 100
_ONLINE_LISTE_ZEICHEN_MAX = 3900

# Wie lange die "Online-Liste posten"-Aufgabe hoechstens stumm auf den
# naechsten PlayerList-Block wartet, bevor sie trotzdem mit dem bisherigen
# Platzhaltertext postet (siehe _scheduled_task_ausfuehren) - und in welchem
# Takt sie es zwischendurch erneut versucht. Der Retry-Takt entspricht bewusst
# scheduled_tasks_loop (30s), ein kuerzerer Wert haette keinen Effekt.
_ONLINE_LISTE_MAX_WARTE_SEKUNDEN = 600
_ONLINE_LISTE_RETRY_SEKUNDEN = 30


# Obergrenze fuer Eintraege aus einer Connect-Meldung. Sie haben kein
# natuerliches Verfallsdatum (der Spieler bleibt online, bis ein Disconnect
# kommt), deshalb braucht es eine harte Grenze fuer den Fall, dass die
# Disconnect-Zeile nie eintrifft – Absturz, Log-Rotation, FTP-Luecke.
_ONLINE_CONNECT_MAX_ALTER = 6 * 3600


async def _a2s_online_namen(conn: ServerConnection) -> Optional[List[str]]:
    """Die ECHTEN Namen der verbundenen Spieler per A2S_PLAYER – direkt vom
    Server, unabhaengig vom ADM-Log und dessen ``adminLog*``-Einstellungen.

    Das ist die primaere Quelle fuer "wer ist online": das Log kennt einen
    Spieler nur ueber Connect-/Positions-Zeilen, die je nach Server-
    Konfiguration fehlen koennen (siehe _online_spieler_namen). A2S_PLAYER
    fragt stattdessen den Server selbst, wie es auch andere DayZ-Bots und
    das Nitrado-Panel tun. ``None`` = keine verwertbare Antwort, dann faellt
    der Aufrufer auf die log-basierte Erkennung zurueck.
    """
    ip = str(conn.get("server_ip") or "").split(":")[0].strip()
    qport = int(conn.get("query_port", 0) or 0)
    if not ip or not qport:
        return None
    try:
        loop = asyncio.get_running_loop()
        namen = await loop.run_in_executor(None, a2s_player_names, ip, qport)
    except Exception as e:  # noqa: BLE001 – Zugabe, darf den Aufrufer nie kippen
        log.debug(f"[A2S] Player-Namen ({conn.name}): {e}")
        return None
    if namen is None:
        return None
    return sorted({n.strip() for n in namen if n and n.strip()}, key=str.lower)


async def _a2s_spielerzahl(conn: ServerConnection) -> Optional[int]:
    """Wie viele Spieler meldet der Server selbst? ``None`` = keine Antwort.

    Derselbe Weg wie beim Status-Embed (_status_update_for): eine
    A2S_INFO-Abfrage im Executor, damit der UDP-Timeout die Aufgaben-
    Schleife nicht anhaelt. Nur noch als Rueckfall gedacht, wenn
    _a2s_online_namen (A2S_PLAYER) keine Antwort liefert – etwa wenn ein
    Server A2S_INFO beantwortet, A2S_PLAYER aber sperrt.
    """
    ip = str(conn.get("server_ip") or "").split(":")[0].strip()
    qport = int(conn.get("query_port", 0) or 0)
    if not ip or not qport:
        return None
    try:
        loop = asyncio.get_running_loop()
        info = await loop.run_in_executor(None, a2s_query, ip, qport)
    except Exception as e:  # noqa: BLE001 – Zugabe, darf den Post nie kippen
        log.debug(f"[AUTO-AUFGABEN] A2S ({conn.name}): {e}")
        return None
    if not info:
        return None
    try:
        return max(0, int(info.get("players", 0)))
    except (TypeError, ValueError):
        return None


def _online_spieler_namen(positions: Dict[str, Dict],
                          max_age_seconds: int = 900,
                          max_connect_age_seconds: int = _ONLINE_CONNECT_MAX_ALTER
                          ) -> List[str]:
    """Wer ist laut Log gerade auf dem Server – unabhaengig von Verknuepfung
    oder einem gesehenen Connect-Event.

    Die sessions-Tabelle (fuer Spielzeit-Belohnung gedacht) faengt nur echte
    "is connected"-Zeilen ab und holt sonst nur VERLINKTE Namen nach
    (sync_sessions_from_positions) – ein Spieler, der schon verbunden war,
    BEVOR Bot oder FTP zuletzt gestartet sind, taucht dort nie auf, obwohl
    er laufend in den Positions-Zeilen des Logs steht (fast jede Aktion
    schreibt "Player "Name" (id=... pos=<...>)"). Deshalb liest die
    Online-Liste direkt aus dem Positions-Tracking – demselben, das auch
    _seen_in_logs fuer die "bist du gerade online"-Pruefung bei /link nutzt,
    daher derselbe Standard-Zeitraum von 900s.

    ZWEI Zeitfenster, weil die Eintraege zwei verschiedene Dinge bedeuten
    (siehe "quelle" in _set_position/_set_gesehen):

    * ``position`` – eine BEILAEUFIGE Positions-Zeile aus irgendeinem
      Ereignis (Kill, Treffer, Bau …), hoechstens 900s alt. Aeltere sagen
      nichts mehr aus, der Spieler kann laengst weg sein.
    * ``connect``/``playerlist`` – eine gesehene "is connected"-Zeile ohne
      Position, oder ein Eintrag aus einem vollstaendigen PlayerList-Block
      (DayZs eigener Momentaufnahme). Beide gelten bis zum Disconnect, bis
      ein neuer PlayerList-Block widerspricht oder bis ein Server-Neustart
      erkannt wird; nur als Notnagel greift die Obergrenze oben. Mit dem
      900s-Fenster fiel ein Spieler, der schon vor dem letzten Bot-Start
      online war und nur ueber den periodischen Block bekannt ist, zwischen
      zwei Block-Durchlaeufen aus der Liste, obwohl er die ganze Zeit da war.
    """
    now = datetime.now(timezone.utc)
    namen = []
    for name, info in positions.items():
        try:
            seen = datetime.fromisoformat(str(info.get("last_seen", "")))
        except (TypeError, ValueError):
            continue
        grenze = (max_connect_age_seconds
                  if info.get("quelle") in ("connect", "playerlist")
                  else max_age_seconds)
        if (now - seen).total_seconds() <= grenze:
            namen.append(name)
    namen.sort(key=str.lower)
    return namen


def _online_liste_embed(conn: ServerConnection, namen: List[str],
                        notiz: str = "",
                        gesamt: Optional[int] = None) -> discord.Embed:
    """Wer ist gerade online? Kopfzeile mit Anzahl, darunter die Namen.

    ``gesamt`` ist die Spielerzahl, die der Server selbst per A2S meldet
    (``None`` = keine Antwort). Sie hat Vorrang vor der Zahl der bekannten
    Namen: schreibt der Server keine Positions-Zeilen, kennt der Bot weniger
    Namen als Spieler da sind – dann steht die richtige Zahl oben und der
    Grund fuer die fehlenden Namen darunter, statt dass der Post eine zu
    kleine Zahl als Wahrheit ausgibt.

    Die Namen kommen aus dem Spiel und sind Fremdeingabe: ohne
    ``escape_markdown`` wuerde aus ``ICH_MAG_HUNDE_xD`` kursiver Text.
    """
    anzahl = max(int(gesamt), len(namen)) if gesamt is not None else len(namen)
    gezeigt = namen[:_ONLINE_LISTE_MAX]
    zeilen: List[str] = []
    laenge = 0
    abgeschnitten = False
    for i, n in enumerate(gezeigt):
        zeile = f"• **{discord.utils.escape_markdown(n)}**"
        # +40 Puffer fuer die spaeter angehaengte "… und N weitere"-Zeile
        if laenge + len(zeile) + 1 > _ONLINE_LISTE_ZEICHEN_MAX - 40:
            abgeschnitten = True
            gezeigt = gezeigt[:i]
            break
        zeilen.append(zeile)
        laenge += len(zeile) + 1
    rest = len(namen) - len(gezeigt)
    if rest > 0:
        zeilen.append(f"… und {rest} weitere"
                      + (" (Namen zu lang für einen Post)" if abgeschnitten else ""))
    if zeilen:
        beschreibung = "\n".join(zeilen)
    elif anzahl > 0:
        # anzahl kommt von A2S (siehe oben) und hat Vorrang - "niemand
        # online" waere hier schlicht falsch und widerspraeche der eigenen
        # Kopfzeile. Kennt der Log-Parser (noch) keine Namen (z. B. direkt
        # nach einem Bot-Neustart, bevor der naechste PlayerList-Block kam),
        # muss das auch so dastehen statt eine leere Liste vorzutaeuschen.
        beschreibung = (f"{anzahl} Spieler laut Server – Namen aktuell nicht "
                        f"bekannt (Log-Tracking noch nicht aufgebaut).")
    else:
        beschreibung = "Gerade ist niemand online."
    e = discord.Embed(
        title=f"📡 • Online-Liste • {anzahl} Spieler",
        description=beschreibung,
        color=0x5865F2,
        timestamp=datetime.now(timezone.utc))
    e.set_footer(text=f"{notiz} · {conn.name}" if notiz else conn.name)
    return e


def _scheduled_tasks(conn: ServerConnection) -> List[Dict]:
    """Die geplanten Aufgaben EINES Servers – nie ein Rueckfall auf einen
    anderen Server oder die globale config, siehe _KEINE_RUECKFALL_SCHLUESSEL."""
    ts = conn.data.get("scheduled_tasks")
    if not isinstance(ts, list):
        ts = []
        conn.set("scheduled_tasks", ts)
    return ts


def _scheduled_tasks_save(conn: ServerConnection) -> None:
    _conn_store(conn, "scheduled_tasks", _scheduled_tasks(conn))


def _find_scheduled_task(conn: ServerConnection, task_id: int) -> Optional[Dict]:
    for t in _scheduled_tasks(conn):
        if isinstance(t, dict) and int(t.get("id", 0)) == task_id:
            return t
    return None


def _naechste_scheduled_task_id(conn: ServerConnection) -> int:
    vorhandene = [int(t.get("id", 0)) for t in _scheduled_tasks(conn) if isinstance(t, dict)]
    return 1 + max(vorhandene or [0])


def _scheduled_task_vorwaerts(next_execution: float, interval_seconds: int,
                              jetzt: Optional[float] = None) -> float:
    """Naechsten faelligen Zeitpunkt ab next_execution finden – bei einer
    laengeren Ausfallzeit des Bots wird so uebersprungen statt die Aufgabe
    fuer jeden verpassten Zyklus auf einmal nachzuholen.

    Die Schleife MUSS unter allen Umstaenden terminieren: sie laeuft im
    Event-Loop, der Discord-Bot UND Dashboard ALLER Kunden bedient. Bei einem
    sehr weit in der Vergangenheit liegenden Startzeitpunkt (z. B. -1e300)
    veraendert ``+= schritt`` die Gleitkommazahl gar nicht mehr – die Schleife
    lief dann endlos und fror den gesamten Prozess ein, fuer jeden Kunden,
    dauerhaft ueber Neustarts hinweg (der Wert steht in connections.json).
    Deshalb hier zwei Sicherungen: unbrauchbare Werte werden sofort auf den
    naechsten regulaeren Zeitpunkt gezogen, und ein Durchlauf ohne Fortschritt
    bricht ab.
    """
    jetzt = jetzt if jetzt is not None else time.time()
    schritt = max(60, int(interval_seconds))
    if not math.isfinite(next_execution) or next_execution <= jetzt - _TASK_MAX_RUECKSTAND:
        # Unbrauchbar oder absurd weit zurueck: gar nicht erst hochzaehlen.
        return jetzt + schritt
    while next_execution <= jetzt:
        vorher = next_execution
        next_execution += schritt
        if next_execution <= vorher:
            # Kein Fortschritt (Gleitkomma-Aufloesung erschoepft) – Notausstieg.
            return jetzt + schritt
    return next_execution


# ══════════════════════════════════════════════════════════════
#  /zone – Überwachte Zonen: wiederholter Ping (alle 5 Min),
#  solange ein Spieler in der Zone steht (außer Allowlist)
#  (Positionen kommen aus den ADM-Logs, Prüfung in _check_zones)
# ══════════════════════════════════════════════════════════════
zone_group = app_commands.Group(name="zone",
                                description=app_commands.locale_str("🛡️ Zonen-Pings verwalten (Admin)"))

def _zones(conn: Optional[ServerConnection] = None) -> List[Dict]:
    """Die Zonen eines Servers. Ohne Angabe die des Hauptservers."""
    src = conn or connections.primary()
    if src is None:
        zs = cfg.config.get("zones")
        if not isinstance(zs, list):
            zs = []
            cfg.config["zones"] = zs
        return zs
    # Bewusst src.data statt src.get: der Rueckfall auf die globale config
    # wuerde sonst allen Servern DIESELBE Zonenliste geben. Migrierte
    # Verbindungen haben ihre Zonen ohnehin bereits in den eigenen Daten.
    zs = src.data.get("zones")
    if not isinstance(zs, list):
        zs = []
        src.set("zones", zs)
    return zs


def _zones_save(conn: Optional[ServerConnection] = None) -> None:
    """Zonen sichern – beim Hauptserver zusaetzlich in der config.json."""
    src = conn or connections.primary()
    if src is not None:
        _conn_store(src, "zones", _zones(src))
    else:
        cfg.save_config()

def _find_zone(name: str, conn: Optional[ServerConnection] = None) -> Optional[Dict]:
    key = name.strip().lower()
    for z in _zones(conn):
        if isinstance(z, dict) and str(z.get("name", "")).strip().lower() == key:
            return z
    return None

def _zone_allowlist(zone: Dict) -> List[str]:
    """Liefert die Ignorier-Liste einer Zone (legt sie bei Bedarf an)."""
    al = zone.get("allowlist")
    if not isinstance(al, list):
        al = []
        zone["allowlist"] = al
    return al

def _allowlist_aus_anfrage(data: Dict) -> Optional[List[str]]:
    """Die im Zonen-Formular gewählten Spielernamen säubern.

    ``None`` heisst "nicht mitgeschickt, vorhandene Liste behalten". Ohne
    diese Auswertung nahmen ``create_zone``/``update_zone`` das Feld
    stillschweigend nicht an: das Dashboard meldete Erfolg, die Namen waren
    aber nie gespeichert und loesten weiter Zonenalarme aus.
    """
    roh = data.get("allowlist")
    if roh is None:
        return None
    if not isinstance(roh, list):
        return []
    namen: List[str] = []
    gesehen: set = set()
    for n in roh:
        name = str(n).strip()[:64]
        if not name:
            continue
        if name.lower() in gesehen:
            continue
        gesehen.add(name.lower())
        namen.append(name)
        if len(namen) >= 200:
            break
    return namen


def _player_in_allowlist(zone: Dict, pname: str) -> bool:
    """True, wenn der Spieler in dieser Zone ignoriert werden soll (case-insensitiv)."""
    key = (pname or "").strip().lower()
    return any(str(n).strip().lower() == key for n in _zone_allowlist(zone))


async def _player_hat_allowlist_rolle(zone: Dict, pname: str) -> bool:
    """True, wenn der Spieler per ``/link`` mit einem Discord-Konto verbunden
    ist, DAS eine der ``manage_role_ids`` ("Allowlist Roles" im Dashboard)
    traegt - die zweite im Zonen-Formular vorgesehene Ignorier-Bedingung.

    War bisher toter Code: ``manage_role_ids`` wurde gespeichert und im
    Formular angezeigt, aber ``_check_zones`` fragte es nie ab - Allowlist
    Roles hatten dadurch nie eine Wirkung, unabhaengig von der Verlinkung.
    """
    role_ids = zone.get("manage_role_ids")
    if not isinstance(role_ids, list) or not role_ids:
        return False
    try:
        gid = int(zone.get("guild_id") or 0)
    except (TypeError, ValueError):
        return False
    if not gid:
        return False
    try:
        rows = db.links_for_name(pname, gid)
    except Exception:  # noqa: BLE001 – Datenbankfehler soll die Zonen-Pruefung nicht abwuergen
        return False
    for row in rows:
        try:
            uid = int(row["user_id"])
        except (TypeError, ValueError, KeyError, IndexError):
            continue
        for rid in role_ids:
            try:
                if await _user_hat_rolle(gid, uid, int(rid)):
                    return True
            except (TypeError, ValueError):
                continue
    return False

def _reset_zone_state(zone_name: str, conn: Optional[ServerConnection] = None):
    """Ping-Cooldowns einer Zone verwerfen (nach remove/edit),
    damit die nächste frische Position sauber neu bewertet wird.

    Mit Verbindung nur die Zone DIESES Servers – sonst setzt eine geloeschte
    Zone „Airfield“ die Cooldowns gleichnamiger Zonen aller Kunden zurueck.
    """
    zk = zone_name.strip().lower()
    sid = conn.service_id if conn is not None else None
    bot._zone_last_ping = {
        k: v for k, v in bot._zone_last_ping.items()
        if not (k[1] == zk and (sid is None or k[0] == sid))}

def _zone_ping_role_ids(zone: Dict) -> List[int]:
    """Rollen, die beim Ping markiert werden – Liste `ping_role_ids`, sonst
    (Altbestand) das frühere einzelne `role_id`."""
    ids = zone.get("ping_role_ids")
    if isinstance(ids, list):
        out = []
        for r in ids:
            try:
                out.append(int(r))
            except (TypeError, ValueError):
                continue
        return out
    legacy = zone.get("role_id")
    return [int(legacy)] if legacy else []


def _zone_payload(z: Dict) -> Dict:
    """Liest eine Zone rückwärtskompatibel: Altbestand ohne `type` gilt als
    `circular`, ein einzelnes altes `role_id` erscheint zusätzlich als Liste
    `ping_role_ids`. Der gespeicherte Eintrag wird dabei NICHT umgeschrieben."""
    out = dict(z)
    out["type"] = z.get("type") or "circular"
    out["ping_role_ids"] = _zone_ping_role_ids(z)
    manage = z.get("manage_role_ids")
    out["manage_role_ids"] = manage if isinstance(manage, list) else []
    out["allowlist"] = _zone_allowlist(z)
    if out["type"] == "polygon":
        pts = z.get("points")
        out["points"] = pts if isinstance(pts, list) else []
    return out


def _ensure_zone_ids(zones: List[Dict]) -> bool:
    """Vergibt fortlaufende `id`-Felder an Zonen, die noch keins haben (reiner
    Anzeigewert, die Ansprache über die API läuft weiter über `name`).
    Gibt True zurück, wenn etwas ergänzt wurde (dann muss gespeichert werden)."""
    changed = False
    next_id = 1 + max([int(z.get("id", 0)) for z in zones if isinstance(z, dict)] or [0])
    for z in zones:
        if isinstance(z, dict) and not z.get("id"):
            z["id"] = next_id
            next_id += 1
            changed = True
    return changed


def _point_in_polygon(px: float, pz: float, points: List[Dict]) -> bool:
    """Ray-Casting-Test: True, wenn (px, pz) innerhalb des Polygons liegt."""
    n = len(points)
    if n < 3:
        return False
    inside = False
    try:
        x1, z1 = float(points[-1]["x"]), float(points[-1]["z"])
        for p in points:
            x2, z2 = float(p["x"]), float(p["z"])
            if (z1 > pz) != (z2 > pz):
                x_schnitt = (x2 - x1) * (pz - z1) / (z2 - z1) + x1
                if px < x_schnitt:
                    inside = not inside
            x1, z1 = x2, z2
    except (TypeError, ValueError, KeyError, ZeroDivisionError):
        return False
    return inside


def _validate_zone_points(points: Any) -> Optional[str]:
    """Gibt eine Fehlermeldung zurück oder None, wenn die Polygon-Punkte ok sind."""
    if not isinstance(points, list) or len(points) < 3:
        return "❌ Ein Polygon braucht mindestens 3 Koordinatenpunkte."
    for p in points:
        if not isinstance(p, dict):
            return "❌ Jeder Polygon-Punkt braucht `x` und `z`."
        try:
            px, pz = float(p.get("x")), float(p.get("z"))
        except (TypeError, ValueError):
            return "❌ Jeder Polygon-Punkt braucht Zahlen für `x` und `z`."
        if not (0.0 <= px <= 20000.0 and 0.0 <= pz <= 20000.0):
            return "❌ Ein Polygon-Punkt liegt außerhalb der Map."
    return None


def _zone_summary(z: Dict) -> str:
    roles = _zone_ping_role_ids(z)
    role = f" · Ping: {' '.join(f'<@&{r}>' for r in roles)}" if roles else ""
    chan = f" · Channel: <#{int(z['channel_id'])}>" if z.get("channel_id") else ""
    if z.get("type") == "polygon":
        pts = z.get("points") or []
        return f"Polygon mit {len(pts)} Punkten{role}{chan}"
    return (f"Zentrum `{z.get('x')}, {z.get('z')}` (x=Ost, z=Nord) · "
            f"Radius **{z.get('radius')} m**{role}{chan}")

async def _zone_name_autocomplete(interaction: discord.Interaction, current: str):
    cur = (current or "").lower()
    conns = _ac_conns(interaction)
    mehrere = len(conns) > 1
    out: List[app_commands.Choice] = []
    for c in conns:
        for z in _zones(c):
            if not (isinstance(z, dict) and z.get("name")):
                continue
            nm = str(z["name"])
            if cur not in nm.lower():
                continue
            out.append(app_commands.Choice(
                name=f"{nm} – {c.name}"[:100] if mehrere else nm, value=nm))
    return out[:25]

def _validate_zone_geometry(x: float, z: float, radius: float) -> Optional[str]:
    """Gibt eine Fehlermeldung zurück oder None, wenn alles ok ist."""
    if not (0.0 <= x <= 20000.0 and 0.0 <= z <= 20000.0):
        return ("❌ Koordinaten außerhalb der Map. Gib die beiden iZurvive-Zahlen "
                "als `x` (Ost) und `z` (Nord) an, z. B. `x: 4522` `z: 9638`.")
    if not (10.0 <= radius <= 10000.0):
        return "❌ Radius muss zwischen **10** und **10000** Metern liegen."
    return None


@zone_group.command(name="list", description=app_commands.locale_str("📋 Alle aktiven Zonen anzeigen (Admin)"))
@app_commands.describe(server="Welcher Nitrado-Server? (nur nötig, wenn mehrere verbunden sind)")
async def zone_list(interaction: discord.Interaction, server: Optional[str] = None):
    if not _subcmd_allowed(interaction, "zone_list"):
        return await _deny_subcmd(interaction)
    _c, _fehler = _conn_waehlen(interaction, server)
    if _c is None:
        return await interaction.response.send_message(_fehler, ephemeral=True)
    zones = [z for z in _zones(_c) if isinstance(z, dict) and z.get("name")]
    if not zones:
        return await interaction.response.send_message(_t(
            interaction,
            "ℹ️ Keine Zonen angelegt. Im Dashboard unter „Zonen“ eine Zone einrichten.",
            "ℹ️ No zones set up. Create one in the dashboard under „Zones“."),
            ephemeral=True)
    e = discord.Embed(title=_t(interaction, f"🛡️ Aktive Zonen ({len(zones)})",
                               f"🛡️ Active Zones ({len(zones)})"), color=0x3498DB)
    for z in zones[:25]:
        e.add_field(name=f"📍 {z['name']}", value=_zone_summary(z), inline=False)
    if len(zones) > 25:
        e.set_footer(text=_t(interaction, f"… und {len(zones) - 25} weitere (Embed-Limit)",
                             f"… and {len(zones) - 25} more (embed limit)"))
    await interaction.response.send_message(embed=e, ephemeral=True)


# ── /zone allowlist – Spieler in einer Zone ignorieren (Admin) ──
allowlist_group = app_commands.Group(
    name="allowlist",
    description=app_commands.locale_str("🙈 Spieler in einer Zone ignorieren (Admin)"),
    parent=zone_group)


@allowlist_group.command(
    name="add",
    description=app_commands.locale_str("🙈 Spieler zur Ignorier-Liste einer Zone hinzufügen (Admin)"))
@app_commands.describe(
    zone="Name der Zone (Autocomplete)",
    spieler="PlayStation-/Ingame-Name, der nicht mehr gemeldet werden soll",
    server="Welcher Nitrado-Server? (nur nötig, wenn mehrere verbunden sind)")
async def zone_allowlist_add(interaction: discord.Interaction, zone: str, spieler: str,
                             server: Optional[str] = None):
    if not _subcmd_allowed(interaction, "zone_allowlist_add"):
        return await _deny_subcmd(interaction)
    _c, _fehler = _conn_waehlen(interaction, server)
    if _c is None:
        return await interaction.response.send_message(_fehler, ephemeral=True)
    z = _find_zone(zone, _c)
    if not z:
        return await interaction.response.send_message(_t(
            interaction,
            f"❌ Keine Zone namens **{zone.strip()}** gefunden – `/zone list` zeigt alle.",
            f"❌ No zone named **{zone.strip()}** found – `/zone list` shows all of them."),
            ephemeral=True)
    spieler = spieler.strip()
    if not spieler:
        return await interaction.response.send_message(_t(
            interaction, "❌ Kein Spielername angegeben.",
            "❌ No player name given."), ephemeral=True)
    if _player_in_allowlist(z, spieler):
        return await interaction.response.send_message(_t(
            interaction,
            f"ℹ️ **{spieler}** steht bereits auf der Ignorier-Liste von **{z['name']}**.",
            f"ℹ️ **{spieler}** is already on the ignore list of **{z['name']}**."),
            ephemeral=True)
    _zone_allowlist(z).append(spieler)
    _zones_save(_c)
    await interaction.response.send_message(_t(
        interaction,
        f"🙈 **{spieler}** wird in Zone **{z['name']}** ab sofort **nicht** mehr gemeldet.",
        f"🙈 **{spieler}** will **no longer** be reported in zone **{z['name']}**."),
        ephemeral=True)

