# Welche Zahlenfelder je Unterbefehl erlaubt sind – haelt api_economy_set_config
# knapp UND verhindert, dass eine Anfrage beliebige neue Schluessel in
# economy/casino einschleust.
_ECONOMY_ZAHLENFELDER = {
    "work":  ("min", "max", "cooldown_seconds"),
    "daily": ("amount", "cooldown_seconds"),
    "beg":   ("min", "max", "cooldown_seconds"),
}
_CASINO_ZAHLENFELDER = {
    "slots":     ("min_bet", "max_bet", "cooldown_seconds"),
    "roulette":  ("min_bet", "max_bet", "cooldown_seconds"),
    "blackjack": ("min_bet", "max_bet", "cooldown_seconds"),
}


def _teilobjekt_mergen(vorhanden: Any, neu: Dict[str, Any],
                       erlaubte_felder: Dict[str, Tuple[str, ...]]
                       ) -> Tuple[Optional[Dict], Optional[str]]:
    """Fügt NUR die im Dashboard gezeigten Zahlenfelder in ``vorhanden`` ein
    (pro Unterschlüssel, z. B. 'work' oder 'slots') – Felder wie
    payout_number oder die Slot-Symbole, die die Oberfläche nicht anzeigt,
    bleiben unangetastet statt beim Speichern einer Karte zu verschwinden."""
    ziel = copy.deepcopy(vorhanden) if isinstance(vorhanden, dict) else {}
    for unterschluessel, werte in neu.items():
        if unterschluessel not in erlaubte_felder:
            return None, f"Unbekannter Bereich: {unterschluessel}"
        if not isinstance(werte, dict):
            return None, f"{unterschluessel} muss ein Objekt sein."
        eintrag = dict(ziel.get(unterschluessel) or {})
        for feld in erlaubte_felder[unterschluessel]:
            if feld not in werte:
                continue
            if werte[feld] is None:
                # Leeres Eingabefeld in der Oberflaeche: als "nicht aendern"
                # lesen. Frueher wurde daraus int(None) und die ganze Karte
                # liess sich nicht mehr speichern.
                continue
            try:
                zahl = int(werte[feld])
            except (TypeError, ValueError):
                return None, f"{unterschluessel}.{feld} muss eine Zahl sein."
            if zahl < 0:
                # Ein negativer Betrag wuerde ueber add_wallet Guthaben
                # VERNICHTEN statt auszuzahlen, ein negativer Cooldown ergibt
                # keinen Sinn.
                return None, f"{unterschluessel}.{feld} darf nicht negativ sein."
            if zahl > _SQLITE_INT_MAX:
                return None, (f"{unterschluessel}.{feld} ist zu groß "
                              f"(höchstens {_SQLITE_INT_MAX}).")
            eintrag[feld] = zahl
        # Vertauschte Grenzen kippen sonst lautlos um (random.randint sortiert
        # selbst) bzw. machen das Spiel unspielbar – lieber sagen, was los ist.
        for klein, gross in (("min", "max"), ("min_bet", "max_bet")):
            if klein in eintrag and gross in eintrag and eintrag[klein] > eintrag[gross]:
                return None, (f"{unterschluessel}: {klein} ({eintrag[klein]}) darf nicht "
                              f"größer sein als {gross} ({eintrag[gross]}).")
        ziel[unterschluessel] = eintrag
    return ziel, None


async def api_economy_set_config(request: web.Request) -> web.Response:
    conn, denied = _session_conn(request)
    if denied is not None:
        return denied
    denied = await _dash_gate(request, conn, "economy", "edit")
    if denied is not None:
        return denied
    denied = _dash_rate_limited(request, "economy.config", 5)
    if denied is not None:
        return denied
    data = await body(request)
    for key in ("currency_name", "currency_symbol"):
        if key in data:
            _conn_store(conn, key, str(data[key]))
    for key in ("starting_balance", "kill_reward", "max_balance_bank", "max_balance_cash"):
        if key not in data or data[key] is None:
            continue        # leeres Feld = nicht aendern
        try:
            wert = int(data[key])
        except (TypeError, ValueError):
            return err(f"{key} muss eine Zahl sein.")
        if wert < 0:
            return err(f"{key} darf nicht negativ sein.")
        # Obergrenze hart klemmen: ein Browser macht aus der Vorgabe
        # 9223372036854775807 beim Bearbeiten 9223372036854776000 (JavaScript
        # rechnet ab ca. 9·10^15 ungenau). Ungeklemmt haette danach JEDE
        # Geldbewegung mit OverflowError abgebrochen – ein Klick auf
        # "Speichern" ohne jede Aenderung haette die Economy lahmgelegt.
        _conn_store(conn, key, min(wert, _SQLITE_INT_MAX))
    for key in ("economy_enabled", "wipe_money_on_leave",
               "prepend_currency_symbol", "check_other_balances"):
        if key in data:
            if not isinstance(data[key], bool):
                return err(f"{key} muss true oder false sein.")
            _conn_store(conn, key, data[key])
    if "check_other_balances_bypass_role_ids" in data:
        roh = data["check_other_balances_bypass_role_ids"]
        if not isinstance(roh, list):
            return err("check_other_balances_bypass_role_ids muss eine Liste sein.")
        try:
            rollen = [str(int(r)) for r in roh]
        except (TypeError, ValueError):
            return err("check_other_balances_bypass_role_ids darf nur Rollen-IDs enthalten.")
        _conn_store(conn, "check_other_balances_bypass_role_ids", rollen)
    if "economy" in data:
        if not isinstance(data["economy"], dict):
            return err("economy muss ein Objekt sein.")
        merged, fehler = _teilobjekt_mergen(conn.get("economy"), data["economy"],
                                            _ECONOMY_ZAHLENFELDER)
        if fehler:
            return err(fehler)
        _conn_store(conn, "economy", merged)
    if "casino" in data:
        if not isinstance(data["casino"], dict):
            return err("casino muss ein Objekt sein.")
        merged, fehler = _teilobjekt_mergen(conn.get("casino"), data["casino"],
                                            _CASINO_ZAHLENFELDER)
        if fehler:
            return err(fehler)
        _conn_store(conn, "casino", merged)
    return ok()


# ──────────────────────────────────────────────────────────────────────────
#  Wiederkehrende Ankündigungen verwalten (announcements.json).
#
#  Schema je Eintrag: ``{day, time, message, channel_id, repeat, last_sent}``.
#  ``day`` = monday…sunday, ``time`` = HH:MM, ``repeat`` = weekly|biweekly|triweekly|monthly.
# ──────────────────────────────────────────────────────────────────────────
_DAYS = ("monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday")
_REPEATS = ("weekly", "biweekly", "triweekly", "monthly")
_DASH_TIME_RE = re.compile(r"^([01]?\d|2[0-3]):([0-5]\d)$")


def _data() -> dict:
    d = ann_data
    if not isinstance(d, dict):
        return {"announcements": []}
    d.setdefault("announcements", [])
    return d


def _ann_visible(request: web.Request) -> Tuple[List[dict], Optional[web.Response]]:
    """Ankündigungen des eigenen Servers.

    Alte Einträge ohne service_id gehören dem Hauptserver – so bleiben
    bestehende Ankündigungen sichtbar, ohne bei Kunden aufzutauchen.
    """
    conn, denied = _session_conn(request)
    if denied is not None:
        return [], denied
    primary = connections.primary()
    eigen = []
    for i, a in enumerate(_data()["announcements"]):
        sid = str(a.get("service_id") or "")
        if sid == conn.service_id or (not sid and primary is conn):
            eigen.append({"index": i, **a})
    return eigen, None


async def list_announcements(request: web.Request) -> web.Response:
    eigen, denied = _ann_visible(request)
    if denied is not None:
        return denied
    denied = await _dash_gate(request, _conn_for_session(_sess_get(request)), "announce", "view")
    if denied is not None:
        return denied
    return ok({"announcements": eigen})


async def create_announcement(request: web.Request) -> web.Response:
    conn, denied = _session_conn(request)
    if denied is not None:
        return denied
    denied = await _dash_gate(request, conn, "announce", "create")
    if denied is not None:
        return denied
    denied = _dash_rate_limited(request, "announce.create", 5)
    if denied is not None:
        return denied
    d = _data()
    data = await body(request)
    day = str(data.get("day", "")).strip().lower()
    time_ = str(data.get("time", "")).strip()
    message = str(data.get("message", "")).strip()
    repeat = str(data.get("repeat", "weekly")).strip().lower()
    channel_id = data.get("channel_id")

    if day not in _DAYS:
        return err("day muss einer von monday…sunday sein.")
    if not _DASH_TIME_RE.match(time_):
        return err("time muss HH:MM sein.")
    if not message:
        return err("Nachricht fehlt.")
    if repeat not in _REPEATS:
        return err("repeat muss weekly, biweekly, triweekly oder monthly sein.")
    if not channel_id:
        return err("channel_id fehlt.")
    try:
        kanal = int(channel_id)
    except (TypeError, ValueError):
        return err("Ungültige Channel-ID.")
    # Der Zielchannel muss in der Guild DIESES Servers liegen. Ohne die
    # Pruefung liess sich mit einer fremden Channel-ID eine wiederkehrende
    # Ankuendigung im Discord eines anderen Kunden einplanen.
    if conn.guild_id is None:
        return err("Für diesen Server ist noch kein Discord-Server zugeordnet – "
                   "der Bot-Betreiber schaltet ihn frei.", 409)
    fehler = _kanal_gehoert_guild(int(conn.guild_id), kanal)
    if fehler is not None:
        return fehler

    ann = {"day": day, "time": time_, "message": message,
           "channel_id": kanal, "repeat": repeat, "last_sent": None,
           "service_id": conn.service_id}
    d["announcements"].append(ann)
    save = save_announcements
    if callable(save):
        save()
    return ok({"index": len(d["announcements"]) - 1, **ann})


async def delete_announcement(request: web.Request) -> web.Response:
    eigen, denied = _ann_visible(request)
    if denied is not None:
        return denied
    denied = await _dash_gate(request, _conn_for_session(_sess_get(request)), "announce", "delete")
    if denied is not None:
        return denied
    denied = _dash_rate_limited(request, "announce.delete", 5)
    if denied is not None:
        return denied
    d = _data()
    try:
        idx = int(request.match_info["index"])
    except ValueError:
        return err("Ungültiger Index.")
    if not 0 <= idx < len(d["announcements"]):
        return err("Ankündigung nicht gefunden.", 404)
    if idx not in [a["index"] for a in eigen]:
        return err("Diese Ankündigung gehört einem anderen Server.", 403)
    removed = d["announcements"].pop(idx)
    save = save_announcements
    if callable(save):
        save()
    return ok({"removed": removed})


# ──────────────────────────────────────────────────────────────────────────
#  Server-Steuerung: Status, Neustart, Stopp (reuse NitradoAPI + A2S).
# ──────────────────────────────────────────────────────────────────────────
async def api_server_status(request: web.Request) -> web.Response:
    a2s = a2s_query
    conn, denied = _session_conn(request)
    if denied is not None:
        return denied
    denied = await _dash_gate(request, conn, "server", "view")
    if denied is not None:
        return denied
    ip = str(conn.get("server_ip") or "")
    port = int(conn.get("query_port", 2302) or 2302)
    live = None
    if callable(a2s) and ip:
        try:
            live = await _dash_run(lambda: a2s(ip, port))
        except Exception:
            live = None
    nit_info = None
    nit = conn.api
    if nit and str(getattr(nit, "service_id", "") or "").strip():
        try:
            info = await nit.get_info()
            if info:
                q = info.get("query") or {}
                nit_info = {
                    "state": info.get("status") or info.get("state"),
                    "players": q.get("player_current"),
                    "max_players": q.get("player_max"),
                    "map": q.get("map"),
                }
        except Exception:
            nit_info = None
    return ok({
        "online": bool(live),
        "a2s": live,
        "nitrado": nit_info,
        "map_name": conn.get("map_name"),
        "server_ip": ip or None,
    })


async def api_server_restart(request: web.Request) -> web.Response:
    denied = await _dash_gate(request, _conn_for_session(_sess_get(request)), "server", "edit")
    if denied is not None:
        return denied
    denied = _dash_rate_limited(request, "server.power", 15)
    if denied is not None:
        return denied
    nit, e = require_nitrado(request)
    if e:
        return e
    okflag, msg = await nit.restart()
    return (ok({"message": msg}) if okflag else err(msg or "Neustart fehlgeschlagen.", 502))


async def api_server_stop(request: web.Request) -> web.Response:
    denied = await _dash_gate(request, _conn_for_session(_sess_get(request)), "server", "edit")
    if denied is not None:
        return denied
    denied = _dash_rate_limited(request, "server.power", 15)
    if denied is not None:
        return denied
    nit, e = require_nitrado(request)
    if e:
        return e
    okflag, msg = await nit.stop()
    return (ok({"message": msg}) if okflag else err(msg or "Stopp fehlgeschlagen.", 502))


