def _lang_von(request: web.Request) -> str:
    """Standard Englisch (siehe app.js: SPRACHE-Erstbesuchs-Standard) - nur
    mit ?lang=de wird ausdruecklich Deutsch angefordert, z. B. vom Footer-
    Link, wenn am Discord-Konto Deutsch als Praeferenz gespeichert ist."""
    return "de" if request.query.get("lang") == "de" else "en"


async def _dash_impressum(request: web.Request) -> web.Response:
    lang = _lang_von(request)
    if lang == "en":
        html = _rechtsseite("en", "Imprint", "Back to dashboard", _IMPRESSUM_EN)
    else:
        html = _rechtsseite("de", "Impressum", "Zurück zum Dashboard", _IMPRESSUM_DE)
    return web.Response(text=html, content_type="text/html", charset="utf-8")


